import{_ as a,o as e,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"OnParameter 距离百分比触发","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/OnParameter.md","filePath":"3. 指令/1. 运动指令/OnParameter.md","lastUpdated":1778862643000}'),n={name:"3. 指令/1. 运动指令/OnParameter.md"};function r(l,t,d,h,o,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="onparameter-距离百分比触发" tabindex="-1">OnParameter 距离百分比触发 <a class="header-anchor" href="#onparameter-距离百分比触发" aria-label="Permalink to &quot;OnParameter 距离百分比触发&quot;">​</a></h1><p>距离百分比触发指令（OnParameter）用于在机器人执行运动轨迹的过程中，在<strong>不打断过渡（Blend）<strong>的前提下，根据当前路径完成的</strong>百分比进度</strong>来触发特定操作（如 IO 输出、变量赋值等）。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>OnParameter(Percence, TimeMs, DO, [Action])</p><p>OnParameter(百分比进度, 时间偏移, 端口号, [动作])</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Percence</td><td>int</td><td>设置触发点在整段路径中所占的百分比（0-100）。例如，设置为 50 表示在路径中点处触发。</td><td>必填</td></tr><tr><td>TimeMs</td><td>int 常量 或 INT 变量</td><td>满足百分比位置条件后的延迟执行时间（单位：ms）。可为负数，负数表示在到达该百分比位置之前提前触发。</td><td>必填</td></tr><tr><td>DO / [Action]</td><td>string / 指令内容</td><td>机器人满足触发条件后执行的指令。支持的操作包括：<strong>IO 指令</strong>（如 <code>SetDO</code>、<code>SetAO</code>、<code>PulseOut</code> 等）和<strong>赋值指令</strong>（对变量进行数值更新）。</td><td>必填</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>当机器人运动到设定的路径百分比位置时，控制器会进入触发等待状态。经过设定的 <code>TimeMs</code> 延时后（若为负数则提前），立即执行 <code>DO</code> 后的相关操作。</p><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>赋值指令</strong></p><p>在机器人从 P1 运动到 P2 的过程中，当路径执行到 60% 的位置时，延时 500ms 将 0 号数字输出口（DO0）置为高电平。</p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C0)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">OnParameter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DO</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SetDO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DO0, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P2, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="关键特性对比" tabindex="-1">关键特性对比 <a class="header-anchor" href="#关键特性对比" aria-label="Permalink to &quot;关键特性对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">OnDistance</th><th style="text-align:left;">OnParameter</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>参考基准</strong></td><td style="text-align:left;">绝对距离（mm）</td><td style="text-align:left;">路径占比（%）</td></tr><tr><td style="text-align:left;"><strong>计算方式</strong></td><td style="text-align:left;">从起点向后或从终点向前</td><td style="text-align:left;">基于整段轨迹的进度比例</td></tr><tr><td style="text-align:left;"><strong>触发特性</strong></td><td style="text-align:left;">不打断过渡、支持时间偏移（正负毫秒）、支持 IO/赋值操作</td><td style="text-align:left;">不打断过渡、支持时间偏移（正负毫秒）、支持 IO/赋值操作</td></tr></tbody></table>`,18)])])}const g=a(n,[["render",r]]);export{c as __pageData,g as default};
